import { useEffect, useRef, useState, useCallback } from "react";
import { lerp, clamp, ease } from "./helpers";

/*
 * ─── ANIMATION TIMELINE ───
 * [startProgress, endProgress]
 * Scaled to use ~85% of the scroll range so no dead space at the end.
 * Container height: 300vh → 200vh of scroll travel.
 */
const T = {
  title:    [0.00, 0.12],
  subtitle: [0.00, 0.12],
  chart:    [0.03, 0.18],
  source:   [0.12, 0.25],
  footer:   [0.12, 0.25],
  divider1: [0.30, 0.38],
  title1:   [0.30, 0.42],
  cards1:   [0.36, 0.52],
  divider2: [0.56, 0.64],
  title2:   [0.56, 0.68],
  cards2:   [0.62, 0.78],
};

function animT(progress, key) {
  const [s, e] = T[key];
  return ease(clamp((progress - s) / (e - s), 0, 1));
}

export default function FraudSection() {
  const [isMobile, setIsMobile] = useState(false);
  const sectionRef = useRef(null);
  const currentP = useRef(0);
  const targetP = useRef(0);
  const rafId = useRef(null);
  const els = useRef({});

  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 768);
    check();
    window.addEventListener("resize", check, { passive: true });
    return () => window.removeEventListener("resize", check);
  }, []);

  const reg = useCallback((key) => (el) => {
    if (el) els.current[key] = el;
  }, []);

  const setEl = (key, t, ty) => {
    const el = els.current[key];
    if (!el) return;
    const y = lerp(ty, 0, t);
    el.style.opacity = t;
    el.style.transform = `translateY(${y}px)`;
  };

  const setElScale = (key, t, ty) => {
    const el = els.current[key];
    if (!el) return;
    const y = lerp(ty, 0, t);
    const s = lerp(0.97, 1, t);
    el.style.opacity = t;
    el.style.transform = `translateY(${y}px) scale(${s})`;
  };

  useEffect(() => {
    let needsPaint = true; // ensures first frame always paints

    const paint = (p) => {
      // Part 1
      setEl("title",    animT(p, "title"),    20);
      setEl("subtitle", animT(p, "subtitle"), 14);
      setEl("chart",    animT(p, "chart"),    14);
      setEl("source",   animT(p, "source"),   0);
      setEl("footer",   animT(p, "footer"),   0);

      // Part 2
      setEl("divider1", animT(p, "divider1"), 0);
      setEl("title1",   animT(p, "title1"),   24);
      for (let i = 0; i < 3; i++) {
        const [s, e] = T.cards1;
        const stagger = i * 0.01;
        const t = ease(clamp((p - s - stagger) / (e - s), 0, 1));
        setElScale(`cards1-${i}`, t, 20);
      }

      // Part 3
      setEl("divider2", animT(p, "divider2"), 0);
      setEl("title2",   animT(p, "title2"),   18);
      for (let i = 0; i < 3; i++) {
        const [s, e] = T.cards2;
        const stagger = i * 0.01;
        const t = ease(clamp((p - s - stagger) / (e - s), 0, 1));
        setEl(`cards2-${i}`, t, 20);
      }
    };

    const tick = () => {
      // Interpolate toward target for smooth motion
      currentP.current += (targetP.current - currentP.current) * 0.12;
      if (Math.abs(targetP.current - currentP.current) < 0.0003) {
        currentP.current = targetP.current;
      }

      paint(currentP.current);

      // Continue if not settled
      if (needsPaint || Math.abs(targetP.current - currentP.current) > 0.0001) {
        needsPaint = false;
        rafId.current = requestAnimationFrame(tick);
      } else {
        rafId.current = null;
      }
    };

    const onScroll = () => {
      const el = sectionRef.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      targetP.current = clamp(
        -rect.top / (el.offsetHeight - window.innerHeight),
        0, 1
      );
      if (!rafId.current) {
        rafId.current = requestAnimationFrame(tick);
      }
    };

    window.addEventListener("scroll", onScroll, { passive: true });

    // Force initial paint after refs are attached
    // Use double-rAF to ensure DOM is ready
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        onScroll();
        // Also do an immediate sync paint in case scroll position is 0
        const el = sectionRef.current;
        if (el) {
          const rect = el.getBoundingClientRect();
          const p = clamp(-rect.top / (el.offsetHeight - window.innerHeight), 0, 1);
          currentP.current = p;
          targetP.current = p;
          paint(p);
        }
      });
    });

    return () => {
      window.removeEventListener("scroll", onScroll);
      if (rafId.current) cancelAnimationFrame(rafId.current);
    };
  }, []);

